CREATE FUNCTION private.column_filter_text_v1(VARIADIC p_values text[]) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $fn$
 SELECT nullif(btrim(value),'') FROM unnest(p_values) WITH ORDINALITY t(value,n) WHERE nullif(btrim(value),'') IS NOT NULL ORDER BY n LIMIT 1
$fn$;
CREATE FUNCTION private.column_filter_phone_v1(value text) RETURNS text LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $fn$
DECLARE digits text; mapped text; prefixes constant jsonb:='{"0162":"032","0163":"033","0164":"034","0165":"035","0166":"036","0167":"037","0168":"038","0169":"039","0120":"070","0121":"079","0122":"077","0126":"076","0128":"078","0123":"083","0124":"084","0125":"085","0127":"081","0129":"082","0186":"056","0188":"058","0199":"059"}';
BEGIN
 IF btrim(value) ~* '^[+-]?\d+(\.\d+)?e[+-]?\d+$' AND length(value)<40 THEN BEGIN value:=trunc(value::numeric)::text; EXCEPTION WHEN numeric_value_out_of_range THEN RETURN NULL; END; END IF;
 digits:=regexp_replace(value,'\D','','g');
 IF left(digits,4)='0084' AND length(digits)>=13 THEN digits:='0'||substr(digits,5);
 ELSIF left(digits,2)='84' AND length(digits)>=11 THEN digits:='0'||substr(digits,3); END IF;
 IF length(digits)=9 AND digits ~ '^[35789]' THEN digits:='0'||digits; END IF;
 IF length(digits)=10 THEN mapped:=prefixes->>('0'||left(digits,3)); IF mapped IS NOT NULL THEN digits:=mapped||substr(digits,4); END IF;
 ELSIF length(digits)=11 THEN mapped:=prefixes->>left(digits,4); IF mapped IS NOT NULL THEN digits:=mapped||substr(digits,5); END IF; END IF;
 RETURN CASE WHEN digits ~ '^0[35789]\d{8}$' THEN digits END;
END $fn$;
CREATE FUNCTION private.column_filter_tag_values_v1(value jsonb) RETURNS text[] LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public AS $fn$
DECLARE item jsonb; result text[]:='{}'; id text;
BEGIN
 IF jsonb_typeof(value)='array' THEN FOR item IN SELECT jsonb_array_elements(value) LOOP result:=result||private.column_filter_tag_values_v1(item); END LOOP; RETURN result;
 ELSIF jsonb_typeof(value)='object' THEN id:=private.column_filter_text_v1(value->>'id',value->>'labelId',value->>'label_id',value->>'tagId',value->>'tag_id');
 ELSE id:=nullif(btrim(value#>>'{}'),''); END IF;
 RETURN CASE WHEN id IS NULL THEN '{}'::text[] ELSE ARRAY[id] END;
END $fn$;
CREATE FUNCTION private.column_filter_zalo_tags_v1(extra jsonb) RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public AS $fn$
 SELECT ARRAY(SELECT DISTINCT id FROM (
 SELECT unnest(private.column_filter_tag_values_v1(extra->key)) id FROM unnest(ARRAY['zaloTagIds','zalo_tag_ids','labelIds','label_ids','tagIds','tag_ids','zaloTags','zalo_tags','labels','tags']) key
 UNION ALL SELECT unnest(private.column_filter_tag_values_v1(extra->'rawPayload'->key)) FROM unnest(ARRAY['labelIds','label_ids','tagIds','tag_ids','zaloTags','zalo_tags','labels','tags']) key
 ) t WHERE id IS NOT NULL)
$fn$;
-- URL component decoding/encoding preserves the existing Desktop source selectors.
CREATE FUNCTION private.column_filter_uri_decode_v1(value text,form boolean DEFAULT false) RETURNS text LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $fn$
DECLARE result bytea:=''::bytea; i integer:=1; ch text;
BEGIN
 WHILE i<=length(value) LOOP
  ch:=substr(value,i,1);
  IF ch='%' THEN
   IF substr(value,i+1,2) !~ '^[0-9a-fA-F]{2}$' THEN RAISE EXCEPTION 'invalid_uri'; END IF;
   result:=result||decode(substr(value,i+1,2),'hex');i:=i+3;
  ELSE result:=result||convert_to(CASE WHEN form AND ch='+' THEN ' ' ELSE ch END,'UTF8');i:=i+1;END IF;
 END LOOP;
 RETURN convert_from(result,'UTF8');
END $fn$;
CREATE FUNCTION private.column_filter_uri_encode_v1(value text,form boolean DEFAULT false) RETURNS text LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $fn$
DECLARE result text:=''; bytes bytea:=convert_to(value,'UTF8'); b integer; i integer;
BEGIN
 FOR i IN 0..length(bytes)-1 LOOP
  b:=get_byte(bytes,i);
  IF (b BETWEEN 65 AND 90) OR (b BETWEEN 97 AND 122) OR (b BETWEEN 48 AND 57) OR b IN (45,46,95,42) OR (NOT form AND b IN (33,39,40,41,126)) THEN result:=result||chr(b);
  ELSIF form AND b=32 THEN result:=result||'+';
  ELSE result:=result||'%'||upper(lpad(to_hex(b),2,'0'));END IF;
 END LOOP;
 RETURN result;
END $fn$;
CREATE FUNCTION private.column_filter_fb_url_v1(value text,kind text) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public AS $fn$
DECLARE raw text:=btrim(value); url text; host text; protocol text; path text; query text; result text; pair text; key text; val text; parts text[]; i integer; removed boolean:=false;
BEGIN
 IF raw IS NULL OR raw='' THEN RETURN NULL; END IF;
 IF kind='profile' THEN raw:=regexp_replace(raw,'^@+',''); END IF;
 IF kind IN ('profile','group') AND raw !~* '(facebook\.com|fb\.com)' THEN
  result:=raw;
  IF kind='group' THEN
   result:=btrim(raw,'/');parts:=array_remove(string_to_array(result,'/'),'');
   IF lower(parts[1])='groups' AND parts[2] IS NOT NULL THEN result:=parts[2]; END IF;
  END IF;
  RETURN CASE WHEN result ~ '^[a-zA-Z0-9._-]+$' THEN lower('https://www.facebook.com/'||CASE WHEN kind='group' THEN 'groups/' ELSE '' END||result) END;
 END IF;
 url:=CASE WHEN raw ~* '^https?://' THEN raw ELSE 'https://'||raw END;
 protocol:=lower(split_part(url,'://',1));host:=lower(substring(url from '^https?://([^/?#]+)'));
 -- WHATWG URL removes default ports. Nondefault ports matter only for post URLs.
 host:=regexp_replace(host,CASE protocol WHEN 'http' THEN ':80$' ELSE ':443$' END,'');
 IF host ~* '@' THEN host:=regexp_replace(host,'^.*@',''); END IF;
 FOREACH key IN ARRAY CASE WHEN kind='post' THEN ARRAY['www','web','m'] ELSE ARRAY['www','web','m','mobile','mbasic'] END LOOP host:=regexp_replace(host,'^'||key||'\.','','i'); END LOOP;
 IF split_part(host,':',1) NOT IN ('facebook.com','fb.com') THEN RETURN NULL; END IF;
 path:=regexp_replace(url,'^https?://[^/?#]+','','i');path:=split_part(path,'#',1);query:=CASE WHEN strpos(path,'?')>0 THEN substr(path,strpos(path,'?')+1) ELSE '' END;path:=split_part(path,'?',1);
 IF path='' THEN path:='/'; END IF;
 IF kind='group' THEN
  parts:=array_remove(string_to_array(path,'/'),'');result:=NULL;
  FOR i IN 1..COALESCE(cardinality(parts),0) LOOP IF lower(parts[i])='groups' THEN result:=parts[i+1];EXIT;END IF;END LOOP;
  result:=btrim(private.column_filter_uri_decode_v1(result));
  RETURN CASE WHEN result ~ '^[a-zA-Z0-9._-]+$' THEN lower('https://www.facebook.com/groups/'||result) END;
 ELSIF kind='profile' THEN
  IF path='/profile.php' THEN
   FOREACH pair IN ARRAY string_to_array(query,'&') LOOP
    IF private.column_filter_uri_decode_v1(split_part(pair,'=',1),true)='id' THEN
     result:=btrim(private.column_filter_uri_decode_v1(CASE WHEN strpos(pair,'=')>0 THEN substr(pair,strpos(pair,'=')+1) ELSE '' END,true));EXIT;
    END IF;
   END LOOP;
   RETURN CASE WHEN nullif(result,'') IS NOT NULL THEN lower('https://www.facebook.com/profile.php?id='||private.column_filter_uri_encode_v1(result)) END;
  END IF;
  parts:=array_remove(string_to_array(path,'/'),'');
  WHILE lower(parts[cardinality(parts)])='friends' LOOP parts:=parts[1:cardinality(parts)-1];END LOOP;
  IF cardinality(parts)<>1 THEN RETURN NULL;END IF;
  result:=btrim(private.column_filter_uri_decode_v1(parts[1]));
  RETURN CASE WHEN result ~ '^[a-zA-Z0-9._-]+$' THEN lower('https://www.facebook.com/'||result) END;
 END IF;
 result:='';
 FOREACH pair IN ARRAY string_to_array(query,'&') LOOP
  IF pair='' THEN CONTINUE;END IF;
  key:=private.column_filter_uri_decode_v1(split_part(pair,'=',1),true);
  IF key ~ '^(__|mibextid$|ref$|locale$|comment_id$|reply_comment_id$)' THEN removed:=true;CONTINUE;END IF;
  val:=private.column_filter_uri_decode_v1(CASE WHEN strpos(pair,'=')>0 THEN substr(pair,strpos(pair,'=')+1) ELSE '' END,true);
  result:=result||CASE WHEN result='' THEN '' ELSE '&' END||private.column_filter_uri_encode_v1(key,true)||'='||private.column_filter_uri_encode_v1(val,true);
 END LOOP;
 IF removed THEN query:=result;END IF;
 RETURN lower(rtrim(protocol||'://www.facebook.com'||CASE WHEN strpos(host,':')>0 THEN ':'||split_part(host,':',2) ELSE '' END||path||CASE WHEN query='' THEN '' ELSE '?'||query END,'/'));
EXCEPTION WHEN data_exception OR raise_exception THEN RETURN lower(rtrim(raw,'/'));
END $fn$;
CREATE FUNCTION private.column_filter_source_match_v1(extra jsonb,query jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public AS $fn$
DECLARE source text:=nullif(btrim(query->>'source'),''); url text; key text; kind text; found boolean;
BEGIN
 url:=private.column_filter_fb_url_v1(query->>'sourcePostUrl','post');
 IF source IS NOT NULL AND url IS NOT NULL AND jsonb_typeof(extra->'sourcePostRefs')='array' AND EXISTS(SELECT 1 FROM jsonb_array_elements(extra->'sourcePostRefs') r WHERE nullif(btrim(r->>'source'),'') IS NOT NULL AND nullif(btrim(COALESCE(nullif(r->>'url',''),r->>'sourcePostUrl')),'') IS NOT NULL) THEN
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(extra->'sourcePostRefs') r WHERE btrim(r->>'source')=source AND private.column_filter_fb_url_v1(COALESCE(nullif(r->>'url',''),r->>'sourcePostUrl'),'post')=url) THEN RETURN false; END IF;
 ELSE
  IF source IS NOT NULL AND btrim(extra->>'source') IS DISTINCT FROM source AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(extra->'sources')='array' THEN extra->'sources' ELSE '[]'::jsonb END) v WHERE btrim(v)=source) THEN RETURN false; END IF;
  IF url IS NOT NULL AND private.column_filter_fb_url_v1(extra->>'sourcePostUrl','post') IS DISTINCT FROM url AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(extra->'sourcePostUrls')='array' THEN extra->'sourcePostUrls' ELSE '[]'::jsonb END) v WHERE private.column_filter_fb_url_v1(v,'post')=url) THEN RETURN false; END IF;
 END IF;
 FOREACH kind IN ARRAY ARRAY['profile','group'] LOOP
  key:=CASE kind WHEN 'profile' THEN 'sourceProfileUrl' ELSE 'sourceGroupUrl' END;url:=private.column_filter_fb_url_v1(query->>key,kind);
  IF url IS NOT NULL AND private.column_filter_fb_url_v1(extra->>key,kind) IS DISTINCT FROM url AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(extra->(key||'s'))='array' THEN extra->(key||'s') ELSE '[]'::jsonb END) v WHERE private.column_filter_fb_url_v1(v,kind)=url) THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
END $fn$;
REVOKE ALL ON FUNCTION private.column_filter_text_v1(text[]),private.column_filter_phone_v1(text),private.column_filter_tag_values_v1(jsonb),private.column_filter_zalo_tags_v1(jsonb),private.column_filter_uri_decode_v1(text,boolean),private.column_filter_uri_encode_v1(text,boolean),private.column_filter_fb_url_v1(text,text),private.column_filter_source_match_v1(jsonb,jsonb) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.aka_agent_read_filtered_group_v1(p_staff_id bigint,p_organization_id bigint,p_auth_username text,p_auth_password text,p_query jsonb)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET statement_timeout='60s' AS $fn$
DECLARE access jsonb; owner_id bigint; group_id bigint; predicate text; sql text; selected_ids bigint[]; total bigint; rows jsonb;
 page_limit integer; page_offset integer; page_cursor jsonb; cursor_clause text:='true'; count_sql text; key text;
BEGIN
 PERFORM public.auto_assert_automation_identity(p_staff_id,p_organization_id,p_auth_username,p_auth_password);
 IF jsonb_typeof(p_query) IS DISTINCT FROM 'object' OR octet_length(p_query::text)>2097152 THEN RAISE EXCEPTION 'invalid_filter_query' USING ERRCODE='22023'; END IF;
 group_id:=(p_query->>'groupId')::bigint;
 access:=private.group_access('data',group_id,p_staff_id,p_organization_id);
 IF access IS NULL THEN RAISE EXCEPTION 'group_access_denied' USING ERRCODE='42501'; END IF;
 owner_id:=(access->>'ownerStaffId')::bigint;
 page_limit:=COALESCE((p_query->>'limit')::integer,100); page_offset:=COALESCE((p_query->>'offset')::integer,0);
 IF page_limit NOT BETWEEN 1 AND 500 OR page_offset NOT BETWEEN 0 AND 100000 OR COALESCE(p_query->>'status','all') NOT IN ('all','active','inactive','friend','stranger','joined','not_joined','request_sent','request_received') THEN RAISE EXCEPTION 'invalid_filter_query' USING ERRCODE='22023'; END IF;
 FOREACH key IN ARRAY ARRAY['accountIds','contactTypes','flatformTypes','datasetIds','dataTypeCategoryItemIds','sourceCodes','ids','excludeIds'] LOOP
  IF p_query ? key AND (jsonb_typeof(p_query->key) IS DISTINCT FROM 'array' OR jsonb_array_length(p_query->key)>CASE WHEN key IN ('ids','excludeIds') THEN 100000 ELSE 1000 END) THEN RAISE EXCEPTION 'invalid_filter_query_array' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(COALESCE(p_query->'sourceCodes','[]')) v WHERE v NOT IN ('upload','scan','automation','dynamic_filter','external_sync')) THEN RAISE EXCEPTION 'invalid_data_group_source_filter'; END IF;
 predicate:=private.column_filter_predicate_v1('data_group',p_query->'columnFilters');
 IF p_query ? 'after' THEN
  IF page_offset<>0
   OR jsonb_typeof(p_query->'after') IS DISTINCT FROM 'object'
   OR jsonb_typeof(p_query#>'{after,id}') IS DISTINCT FROM 'string'
   OR (p_query#>>'{after,id}') !~ '^[1-9][0-9]{0,15}$'
   OR jsonb_typeof(p_query#>'{after,createdAt}') IS DISTINCT FROM 'string'
   OR (p_query#>>'{after,createdAt}') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$' THEN RAISE EXCEPTION 'invalid_filter_cursor' USING ERRCODE='22023'; END IF;
  BEGIN
   IF (p_query#>>'{after,id}')::bigint>9007199254740991 OR NOT isfinite((p_query#>>'{after,createdAt}')::timestamptz) THEN
    RAISE EXCEPTION 'invalid_filter_cursor' USING ERRCODE='22023';
   END IF;
   
  EXCEPTION WHEN data_exception THEN RAISE EXCEPTION 'invalid_filter_cursor' USING ERRCODE='22023'; END;
  cursor_clause:=$cursor$(member_created_at,selected_member_id)<(($3#>>'{after,createdAt}')::timestamptz,($3#>>'{after,id}')::bigint)$cursor$;
 END IF;
 count_sql:=CASE WHEN p_query->>'countMode'='none' THEN 'NULL::bigint' ELSE '(SELECT count(*) FROM matched)' END;
 sql:=$query$
 WITH params AS (SELECT $1::bigint AS p_staff_id,
$2::bigint AS p_organization_id,
$4::bigint AS p_viewer_id,
($3->>'groupId')::bigint AS p_group_id,
$3->>'search' AS p_search,
COALESCE(($3->>'includeAccountless')::boolean,true) AS p_include_accountless,
COALESCE($3->>'status','all') AS p_status,
CASE WHEN jsonb_array_length(COALESCE($3->'accountIds','[]'::jsonb))>0 THEN ARRAY(SELECT jsonb_array_elements_text($3->'accountIds')::bigint) END AS p_account_ids,
CASE WHEN jsonb_array_length(COALESCE($3->'contactTypes','[]'::jsonb))>0 THEN ARRAY(SELECT jsonb_array_elements_text($3->'contactTypes')::text) END AS p_contact_types,
CASE WHEN jsonb_array_length(COALESCE($3->'flatformTypes','[]'::jsonb))>0 THEN ARRAY(SELECT jsonb_array_elements_text($3->'flatformTypes')::text) END AS p_flatform_types,
CASE WHEN jsonb_array_length(COALESCE($3->'datasetIds','[]'::jsonb))>0 THEN ARRAY(SELECT jsonb_array_elements_text($3->'datasetIds')::bigint) END AS p_dataset_ids,
CASE WHEN jsonb_array_length(COALESCE($3->'dataTypeCategoryItemIds','[]'::jsonb))>0 THEN ARRAY(SELECT jsonb_array_elements_text($3->'dataTypeCategoryItemIds')::bigint) END AS p_data_type_category_item_ids,
CASE WHEN jsonb_array_length(COALESCE($3->'sourceCodes','[]'::jsonb))>0 THEN ARRAY(SELECT jsonb_array_elements_text($3->'sourceCodes')::text) END AS p_source_codes,
CASE WHEN jsonb_array_length(COALESCE($3->'ids','[]'::jsonb))>0 THEN ARRAY(SELECT jsonb_array_elements_text($3->'ids')::bigint) END AS p_ids,
CASE WHEN jsonb_array_length(COALESCE($3->'excludeIds','[]'::jsonb))>0 THEN ARRAY(SELECT jsonb_array_elements_text($3->'excludeIds')::bigint) END AS p_exclude_ids), candidate AS (SELECT
      member.id AS selected_member_id,
      member.group_id AS selected_group_id,
      member.contact_id,
      member.created_at AS member_created_at,
      member.updated_at AS member_updated_at,
      member.is_delete AS member_is_delete,
      member.change_revision,
      member.primary_origin_id,
      contact.name,
      contact.uid,
      contact.url,
      contact.phone,
      contact.email,
      contact.extra_data,
      contact.contact_type,
      contact.flatform_type,
      contact.account_id,
      contact.is_friend,
      contact.is_joined,
      account.name AS selected_account_name,
      COALESCE(account.is_delete, false) AS selected_account_deleted
    ,
COALESCE(NULLIF(CASE WHEN contact.flatform_type='zalo' THEN COALESCE(NULLIF(u.zalo_name,''),NULLIF(z.zalo_name,''),contact.name) END,''),NULLIF(contact.name,''),contact.email) AS "f_name",
CASE WHEN contact.flatform_type='zalo' THEN COALESCE(NULLIF(u.display_name,''),NULLIF(u.zalo_name,''),NULLIF(z.display_name,''),NULLIF(z.zalo_name,''),contact.name) END AS "f_displayName",
COALESCE(NULLIF(contact.uid,''),contact.email) AS "f_uid",
contact.phone AS "f_phone",
contact.url AS "f_url",
contact.email AS "f_email",
contact.account_id::text AS "f_account",
origin.data_type_category_item_id::text AS "f_dataType",
CASE WHEN contact.contact_type='group' THEN CASE WHEN contact.is_joined IS TRUE THEN 'joined' ELSE 'not_joined' END
 WHEN contact.flatform_type='zalo' AND contact.contact_type='person' THEN
  CASE WHEN u.id IS NOT NULL THEN CASE WHEN status.code IN ('friend','request_sent','request_received') THEN status.code ELSE 'stranger' END
   WHEN contact.is_friend IS TRUE THEN 'friend'
   WHEN COALESCE(contact.extra_data->>'friendRequestReceived',contact.extra_data->>'friend_request_received','false')='true' THEN 'request_received'
   WHEN COALESCE(contact.extra_data->>'friendRequestSent',contact.extra_data->>'friend_request_sent','false')='true' THEN 'request_sent' ELSE 'stranger' END
 WHEN contact.contact_type='person' THEN CASE WHEN contact.is_friend THEN 'friend' WHEN NOT contact.is_friend THEN 'stranger' ELSE 'unknown' END
 ELSE NULL END AS "f_status",
CASE WHEN source_type.id IS NOT NULL THEN source_category.code END AS "f_source",
CASE WHEN p_viewer_id=p_staff_id AND source_type.id IS NOT NULL AND source_category.code='automation' THEN COALESCE(NULLIF(btrim(automation.name),''),NULLIF(btrim(origin.source_name_snapshot),'')) END AS "f_automation",
contact.extra_data->>'info1' AS "f_info1",
contact.extra_data->>'info2' AS "f_info2",
contact.extra_data->>'info3' AS "f_info3",
contact.extra_data->>'info4' AS "f_info4",
contact.extra_data->>'info5' AS "f_info5"
    FROM public.auto_account_contact_group_members AS member
    CROSS JOIN params
    JOIN public.auto_account_contacts AS contact
      ON contact.id = member.contact_id
    LEFT JOIN public.auto_accounts AS account
      ON account.id = contact.account_id
    LEFT JOIN public.zalo_users z ON z.account_id=contact.account_id AND z.zalo_uid=contact.uid
      AND z.staff_id=contact.staff_id AND z.organization_id=contact.organization_id AND contact.flatform_type='zalo'
    LEFT JOIN public.chat_zalo_account_organization b ON b.auto_account_id=contact.account_id
      AND b.organization_id=contact.organization_id AND b.is_active AND contact.flatform_type='zalo'
    LEFT JOIN public.chat_zalo_account_user u ON u.chat_zalo_account_id=b.chat_zalo_account_id
      AND u.zalo_id=contact.uid AND contact.contact_type='person'
    LEFT JOIN public.category_item status ON status.id=u.friendship_status_category_item_id
    LEFT JOIN public.auto_account_contact_group_member_origins origin ON origin.id=member.primary_origin_id AND origin.membership_id=member.id AND origin.is_current
 LEFT JOIN public.category_item source_category ON source_category.id=origin.source_category_item_id AND source_category.is_active AND source_category.managed_by='system' AND source_category.code=public.aka_agent_data_group_source_code(origin.kind)
 LEFT JOIN public.category_type source_type ON source_type.id=source_category.category_type_id AND source_type.namespace='common' AND source_type.code='data_source' AND source_type.managed_by='system' AND source_type.is_active
 LEFT JOIN public.auto_automation_detail automation_detail ON automation_detail.id=origin.automation_detail_id AND automation_detail.staff_id=p_staff_id AND automation_detail.organization_id=p_organization_id
 LEFT JOIN public.auto_automation automation ON automation.id=automation_detail.automation_id AND automation.staff_id=p_staff_id AND automation.organization_id=p_organization_id
 WHERE member.group_id = p_group_id
      AND contact.staff_id = p_staff_id
      AND contact.organization_id = p_organization_id
      AND member.is_delete = false
      AND (
        COALESCE(p_status, 'all') = 'all'
        OR (
          COALESCE(p_status, 'all') = 'active' AND (
            (contact.contact_type = 'person' AND contact.is_friend = true)
            OR (contact.contact_type = 'group' AND contact.is_joined = true)
            OR contact.contact_type NOT IN ('person', 'group')
          )
        )
        OR (
          COALESCE(p_status, 'all') = 'inactive' AND (
            (contact.contact_type = 'person' AND contact.is_friend = false)
            OR (contact.contact_type = 'group' AND contact.is_joined = false)
          )
        )
        OR (
          COALESCE(p_status, 'all') = 'friend'
          AND contact.contact_type = 'person'
          AND CASE WHEN contact.flatform_type='zalo' THEN (CASE WHEN contact.flatform_type='zalo' AND contact.contact_type='person' THEN
        CASE WHEN u.id IS NOT NULL THEN CASE WHEN status.code IN ('friend','request_sent','request_received') THEN status.code ELSE 'stranger' END
          WHEN contact.is_friend IS TRUE THEN 'friend'
          WHEN COALESCE(contact.extra_data->>'friendRequestReceived',contact.extra_data->>'friend_request_received','false')='true' THEN 'request_received'
          WHEN COALESCE(contact.extra_data->>'friendRequestSent',contact.extra_data->>'friend_request_sent','false')='true' THEN 'request_sent'
          ELSE 'stranger' END END)='friend' ELSE contact.is_friend=true END
        )
        OR (
          COALESCE(p_status, 'all') = 'stranger'
          AND contact.contact_type = 'person'
          AND CASE WHEN contact.flatform_type='zalo' THEN (CASE WHEN contact.flatform_type='zalo' AND contact.contact_type='person' THEN
        CASE WHEN u.id IS NOT NULL THEN CASE WHEN status.code IN ('friend','request_sent','request_received') THEN status.code ELSE 'stranger' END
          WHEN contact.is_friend IS TRUE THEN 'friend'
          WHEN COALESCE(contact.extra_data->>'friendRequestReceived',contact.extra_data->>'friend_request_received','false')='true' THEN 'request_received'
          WHEN COALESCE(contact.extra_data->>'friendRequestSent',contact.extra_data->>'friend_request_sent','false')='true' THEN 'request_sent'
          ELSE 'stranger' END END)='stranger' ELSE contact.is_friend=false END
        )
        OR (p_status IN ('request_sent','request_received') AND contact.flatform_type='zalo' AND contact.contact_type='person' AND (CASE WHEN contact.flatform_type='zalo' AND contact.contact_type='person' THEN
        CASE WHEN u.id IS NOT NULL THEN CASE WHEN status.code IN ('friend','request_sent','request_received') THEN status.code ELSE 'stranger' END
          WHEN contact.is_friend IS TRUE THEN 'friend'
          WHEN COALESCE(contact.extra_data->>'friendRequestReceived',contact.extra_data->>'friend_request_received','false')='true' THEN 'request_received'
          WHEN COALESCE(contact.extra_data->>'friendRequestSent',contact.extra_data->>'friend_request_sent','false')='true' THEN 'request_sent'
          ELSE 'stranger' END END)=p_status)
        OR (
          COALESCE(p_status, 'all') = 'joined'
          AND contact.contact_type = 'group'
          AND contact.is_joined = true
        )
        OR (
          COALESCE(p_status, 'all') = 'not_joined'
          AND contact.contact_type = 'group'
          AND contact.is_joined = false
        )
      )
      AND (
        NULLIF(btrim(COALESCE(p_search, '')), '') IS NULL
        OR contact.name ILIKE '%%' || btrim(p_search) || '%%'
        OR (CASE WHEN contact.flatform_type='zalo' THEN COALESCE(NULLIF(u.zalo_name,''),NULLIF(z.zalo_name,''),contact.name) END) ILIKE '%%' || btrim(p_search) || '%%'
        OR (CASE WHEN contact.flatform_type='zalo' THEN COALESCE(NULLIF(u.display_name,''),NULLIF(u.zalo_name,''),NULLIF(z.display_name,''),NULLIF(z.zalo_name,''),contact.name) END) ILIKE '%%' || btrim(p_search) || '%%'
        OR contact.uid ILIKE '%%' || btrim(p_search) || '%%'
        OR contact.phone ILIKE '%%' || btrim(p_search) || '%%'
        OR contact.email ILIKE '%%' || btrim(p_search) || '%%'
      )
      AND (
        p_account_ids IS NULL
        OR contact.account_id = ANY(p_account_ids)
        OR (
          COALESCE(p_include_accountless, true)
          AND contact.account_id IS NULL
        )
      )
      AND (
        COALESCE(p_include_accountless, true)
        OR contact.account_id IS NOT NULL
      )
      AND (
        p_contact_types IS NULL
        OR contact.contact_type = ANY(p_contact_types)
      )
      AND (
        p_flatform_types IS NULL
        OR contact.flatform_type = ANY(p_flatform_types)
      )
      AND (p_ids IS NULL OR member.id = ANY(p_ids))
      AND (
        p_exclude_ids IS NULL
        OR NOT (member.id = ANY(p_exclude_ids))
      )
      AND (
        p_dataset_ids IS NULL OR EXISTS (
          SELECT 1
          FROM public.auto_account_contact_group_member_origins AS dataset_origin
          WHERE dataset_origin.membership_id = member.id
            AND dataset_origin.dataset_id = ANY(p_dataset_ids)
            AND dataset_origin.is_current = true
        )
      )
 AND (p_data_type_category_item_ids IS NULL OR origin.data_type_category_item_id=ANY(p_data_type_category_item_ids))
 AND (p_source_codes IS NULL OR EXISTS(SELECT 1 FROM public.auto_account_contact_group_member_origins o JOIN public.category_item c ON c.id=o.source_category_item_id WHERE o.membership_id=member.id AND o.is_current AND c.code=ANY(p_source_codes)))
),
 matched AS %4$s (SELECT selected_member_id,member_created_at FROM candidate WHERE %1$s),
 page AS MATERIALIZED (SELECT * FROM matched WHERE %2$s ORDER BY member_created_at DESC,selected_member_id DESC OFFSET $5 LIMIT $6)
 SELECT (SELECT array_agg(selected_member_id ORDER BY member_created_at DESC,selected_member_id DESC) FROM page), %3$s,
 (SELECT jsonb_build_object('createdAt',member_created_at,'id',selected_member_id::text) FROM page ORDER BY member_created_at,selected_member_id LIMIT 1)
 $query$;
 sql:=format(sql,predicate,cursor_clause,count_sql,CASE WHEN p_query->>'countMode'='none' THEN 'NOT MATERIALIZED' ELSE 'MATERIALIZED' END);
 EXECUTE sql INTO selected_ids,total,page_cursor USING owner_id,p_organization_id,p_query,p_staff_id,page_offset,page_limit;
 IF p_query->>'idsOnly'='true' THEN
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',v) ORDER BY n),'[]'::jsonb) INTO rows FROM unnest(selected_ids) WITH ORDINALITY t(v,n);
 ELSIF cardinality(selected_ids)>0 THEN
  SELECT COALESCE(jsonb_agg(CASE WHEN owner_id=p_staff_id THEN m-'total_count' ELSE (m-'total_count')||jsonb_build_object('source_automation_id',NULL,'source_automation_name',NULL,'dataset_ids','[]'::jsonb,'dataset_names','[]'::jsonb,'provenance','[]'::jsonb) END),'[]') INTO rows
  FROM private.read_shared_group_members(owner_id,p_organization_id,group_id,NULL,NULL,true,NULL,NULL,'all',NULL,NULL,selected_ids,NULL,0,page_limit) m;
 ELSE rows:='[]'; END IF;
 RETURN jsonb_build_object('version',1,'rows',rows,'total',total,'after',page_cursor,'hasMore',COALESCE(cardinality(selected_ids),0)=page_limit);
END $fn$;
REVOKE ALL ON FUNCTION public.aka_agent_read_filtered_group_v1(bigint,bigint,text,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aka_agent_read_filtered_group_v1(bigint,bigint,text,text,jsonb) TO anon,authenticated,service_role;

CREATE FUNCTION public.aka_agent_read_filtered_contacts_v1(p_staff_id bigint,p_organization_id bigint,p_auth_username text,p_auth_password text,p_source text,p_query jsonb)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET statement_timeout='60s' AS $fn$
DECLARE predicate text; sql text; result jsonb; page_limit integer; page_offset integer; key text; cursor_clause text:='true'; count_sql text;
BEGIN
 PERFORM public.auto_assert_automation_identity(p_staff_id,p_organization_id,p_auth_username,p_auth_password);
 IF p_source IS NULL OR p_source NOT IN ('contacts','upload','group_members') OR jsonb_typeof(p_query) IS DISTINCT FROM 'object' OR octet_length(p_query::text)>2097152 THEN RAISE EXCEPTION 'invalid_filter_query'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.org_staff s WHERE s.id=p_staff_id AND s.organization_id=p_organization_id AND s.is_active AND s.deleted_at IS NULL) OR NOT EXISTS(SELECT 1 FROM public.auto_accounts a WHERE a.id=(p_query->>'accountId')::bigint AND a.staff_id=p_staff_id AND a.organization_id=p_organization_id AND NOT a.is_delete) THEN RAISE EXCEPTION 'account_access_denied' USING ERRCODE='42501'; END IF;
 IF p_source='group_members' AND nullif(btrim(p_query->>'zaloGroupId'),'') IS NULL THEN RAISE EXCEPTION 'group_required'; END IF;
 IF p_query ? 'datasetId' AND NOT EXISTS(SELECT 1 FROM public.auto_account_contacts_dataset d WHERE d.id=(p_query->>'datasetId')::bigint AND d.staff_id=p_staff_id AND d.organization_id=p_organization_id AND d.account_id=(p_query->>'accountId')::bigint AND NOT d.is_delete AND (p_query->>'contactType' IS NULL OR d.contact_type=p_query->>'contactType')) THEN RAISE EXCEPTION 'dataset_access_denied' USING ERRCODE='42501'; END IF;
 IF p_query ? 'contactGroupId' AND NOT EXISTS(SELECT 1 FROM public.auto_account_contact_groups g WHERE g.id=(p_query->>'contactGroupId')::bigint AND g.staff_id=p_staff_id AND g.organization_id=p_organization_id AND g.account_id IS NULL AND g.contact_type IS NULL AND g.purpose='data_group' AND NOT g.is_delete) THEN RAISE EXCEPTION 'group_access_denied' USING ERRCODE='42501'; END IF;
 page_limit:=COALESCE((p_query->>'limit')::integer,100);page_offset:=COALESCE((p_query->>'offset')::integer,0);
 IF page_limit NOT BETWEEN 1 AND 500 OR page_offset NOT BETWEEN 0 AND 100000 OR COALESCE(p_query->>'statusFilter','all') NOT IN ('all','active','inactive') THEN RAISE EXCEPTION 'invalid_filter_query'; END IF;
 FOREACH key IN ARRAY ARRAY['ids','excludeIds','zaloTagIds','akaBizTagIds'] LOOP
  IF p_query ? key AND (jsonb_typeof(p_query->key) IS DISTINCT FROM 'array' OR jsonb_array_length(p_query->key)>CASE WHEN key IN ('ids','excludeIds') THEN 100000 ELSE 1000 END) THEN RAISE EXCEPTION 'invalid_filter_query_array'; END IF;
  IF p_query->key='[]'::jsonb THEN p_query:=p_query-key; END IF;
 END LOOP;
 predicate:=private.column_filter_predicate_v1(p_source,p_query->'columnFilters');
 IF p_query ? 'after' THEN
  IF page_offset<>0
   OR jsonb_typeof(p_query->'after') IS DISTINCT FROM 'object'
   OR jsonb_typeof(p_query#>'{after,id}') IS DISTINCT FROM 'string'
   OR (p_query#>>'{after,id}') !~ '^[1-9][0-9]{0,15}$'
   OR jsonb_typeof(p_query#>'{after,time}') IS DISTINCT FROM 'string'
   OR (p_query#>>'{after,time}') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'
   OR jsonb_typeof(p_query#>'{after,rank}') IS DISTINCT FROM 'number'
   OR (p_query#>>'{after,rank}') !~ '^[0-9]{1,10}$'
   OR jsonb_typeof(p_query#>'{after,name}') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'invalid_filter_cursor' USING ERRCODE='22023'; END IF;
  BEGIN
   IF (p_query#>>'{after,id}')::bigint>9007199254740991 OR NOT isfinite((p_query#>>'{after,time}')::timestamptz) THEN
    RAISE EXCEPTION 'invalid_filter_cursor' USING ERRCODE='22023';
   END IF;
   PERFORM (p_query#>>'{after,rank}')::integer;
  EXCEPTION WHEN data_exception THEN RAISE EXCEPTION 'invalid_filter_cursor' USING ERRCODE='22023'; END;
  cursor_clause:=$cursor$(sort_rank,sort_name,-extract(epoch FROM sort_time),id)>((($3#>>'{after,rank}')::integer),($3#>>'{after,name}'),-extract(epoch FROM ($3#>>'{after,time}')::timestamptz),($3#>>'{after,id}')::bigint)$cursor$;
 END IF;
 count_sql:=CASE WHEN p_query->>'countMode'='none' THEN 'NULL::bigint' ELSE '(SELECT count(*) FROM matched)' END;
 sql:=$query$
 WITH candidate AS NOT MATERIALIZED (SELECT c.id,
 CASE WHEN $4='group_members' OR $3->>'sortBy'='zalo_group_role' THEN (CASE WHEN gm.id IS NOT NULL THEN COALESCE(gm.role_rank,3) WHEN c.extra_data->>'zaloGroupRoleRank' IN ('1','2','3') THEN (c.extra_data->>'zaloGroupRoleRank')::integer WHEN c.extra_data->>'zaloGroupRole'='owner' OR c.extra_data->>'isCreator'='true' THEN 1 WHEN c.extra_data->>'zaloGroupRole'='admin' OR c.extra_data->>'isAdmin'='true' THEN 2 ELSE 3 END) WHEN $3 ? 'datasetId' THEN COALESCE(dm.sort_order,2147483647) ELSE 0 END sort_rank,
 CASE WHEN $4='group_members' OR $3 ? 'datasetId' THEN '' ELSE COALESCE(c.name,'') END sort_name,
 CASE WHEN $4='group_members' THEN COALESCE(gm.updated_at,'epoch'::timestamptz) ELSE 'epoch'::timestamptz END sort_time,
 to_jsonb(c)||jsonb_build_object('extra_data',COALESCE(c.extra_data,'{}'::jsonb)
 || CASE WHEN zu.id IS NOT NULL AND $4<>'group_members' THEN jsonb_build_object('gender',zu.gender) ELSE '{}'::jsonb END
 || CASE WHEN zg.id IS NOT NULL THEN jsonb_build_object('totalMember',zg.total_member,'groupType',zg.group_type) ELSE '{}'::jsonb END
 || CASE WHEN gm.id IS NOT NULL THEN jsonb_build_object('zaloGroupId',gm.zalo_group_id,'zaloGroupRole',gm.role,'zaloGroupRoleRank',gm.role_rank,'isCreator',gm.is_creator,'isAdmin',gm.is_admin,'zaloGroupRoleLabel',CASE WHEN gm.role='owner' THEN CASE WHEN mg.group_type=2 THEN 'Trưởng cộng đồng' ELSE 'Trưởng nhóm' END WHEN gm.role='admin' THEN CASE WHEN mg.group_type=2 THEN 'Phó cộng đồng' ELSE 'Phó nhóm' END ELSE 'Thành viên' END) ELSE '{}'::jsonb END) row_data,
 c.name AS "f_name", CASE WHEN $4='upload' THEN COALESCE(NULLIF(btrim(btrim(COALESCE(c.extra_data->>'uid',c.extra_data#>>'{rawPayload,uid}'))),''),NULLIF(btrim(btrim(COALESCE(c.extra_data->>'url',c.extra_data#>>'{rawPayload,url}'))),''),NULLIF(btrim(c.url),''),NULLIF(btrim(CASE WHEN c.contact_type NOT IN ('phone','email') THEN c.uid END),'')) ELSE c.uid END AS "f_uid", CASE WHEN $4='upload' THEN COALESCE(NULLIF(btrim(btrim(COALESCE(c.extra_data->>'phone',c.extra_data#>>'{rawPayload,phone}'))),''),NULLIF(btrim(COALESCE(NULLIF(btrim(c.extra_data->>'phoneNumber'),''),NULLIF(btrim(c.extra_data->>'phone_number'),''),NULLIF(btrim(c.extra_data#>>'{rawPayload,phoneNumber}'),''),NULLIF(btrim(c.extra_data#>>'{rawPayload,phone_number}'),''))),''),NULLIF(btrim(CASE WHEN c.contact_type='phone' THEN c.uid END),'')) ELSE private.column_filter_phone_v1(COALESCE(NULLIF(btrim(c.extra_data->>'phone'),''),NULLIF(btrim(c.extra_data->>'phoneNumber'),''),NULLIF(btrim(c.extra_data->>'phone_number'),''),NULLIF(btrim(c.extra_data->>'mobilePhone'),''),NULLIF(btrim(c.extra_data->>'mobile_phone'),''),NULLIF(btrim(c.extra_data#>>'{rawPayload,phone}'),''),NULLIF(btrim(c.extra_data#>>'{rawPayload,phoneNumber}'),''),NULLIF(btrim(c.extra_data#>>'{rawPayload,phone_number}'),''),NULLIF(btrim(c.extra_data#>>'{rawPayload,mobilePhone}'),''),NULLIF(btrim(c.extra_data#>>'{rawPayload,mobile_phone}'),''))) END AS "f_phone", c.url AS "f_url", COALESCE(NULLIF(btrim(btrim(COALESCE(c.extra_data->>'email',c.extra_data#>>'{rawPayload,email}'))),''),NULLIF(btrim(CASE WHEN c.contact_type='email' THEN c.uid END),'')) AS "f_email", COALESCE(NULLIF(c.extra_data->>'avatarUrl',''),NULLIF(c.extra_data->>'avatar',''),NULLIF(c.extra_data->>'avatar_url',''),NULLIF(c.extra_data->>'fullAvatar',''),NULLIF(c.extra_data->>'full_avatar','')) AS "f_avatar", CASE (CASE WHEN zu.id IS NOT NULL AND $4<>'group_members' THEN zu.gender::text ELSE c.extra_data->>'gender' END) WHEN '0' THEN 'male' WHEN '1' THEN 'female' ELSE 'unknown' END AS "f_gender", private.column_filter_zalo_tags_v1(c.extra_data) AS "f_zaloTags", c.akabiz_tag_ids::text[] AS "f_akaBizTags", CASE WHEN zg.id IS NOT NULL THEN zg.total_member::numeric WHEN c.extra_data->>'totalMember' ~ '^[-+]?[0-9]+([.][0-9]+)?$' THEN (c.extra_data->>'totalMember')::numeric END AS "f_memberCount", CASE (CASE WHEN gm.id IS NOT NULL THEN COALESCE(gm.role_rank,3) WHEN c.extra_data->>'zaloGroupRoleRank' IN ('1','2','3') THEN (c.extra_data->>'zaloGroupRoleRank')::integer WHEN c.extra_data->>'zaloGroupRole'='owner' OR c.extra_data->>'isCreator'='true' THEN 1 WHEN c.extra_data->>'zaloGroupRole'='admin' OR c.extra_data->>'isAdmin'='true' THEN 2 ELSE 3 END) WHEN 1 THEN 'owner' WHEN 2 THEN 'admin' ELSE 'member' END AS "f_role", CASE WHEN c.is_friend THEN 'friend' WHEN NOT c.is_friend THEN 'stranger' ELSE 'unknown' END AS "f_friendship", CASE WHEN c.is_joined THEN 'joined' ELSE 'not_joined' END AS "f_joined", CASE WHEN c.requires_post_approval THEN 'required' WHEN NOT c.requires_post_approval THEN 'not_required' ELSE 'unknown' END AS "f_approval", btrim(COALESCE(c.extra_data->>'info1',c.extra_data#>>'{rawPayload,info1}')) AS "f_info1", btrim(COALESCE(c.extra_data->>'info2',c.extra_data#>>'{rawPayload,info2}')) AS "f_info2", btrim(COALESCE(c.extra_data->>'info3',c.extra_data#>>'{rawPayload,info3}')) AS "f_info3", btrim(COALESCE(c.extra_data->>'info4',c.extra_data#>>'{rawPayload,info4}')) AS "f_info4", btrim(COALESCE(c.extra_data->>'info5',c.extra_data#>>'{rawPayload,info5}')) AS "f_info5"
 FROM public.auto_account_contacts c
 LEFT JOIN public.auto_account_contacts_dataset_members dm ON dm.dataset_id=($3->>'datasetId')::bigint AND dm.contact_id=c.id AND dm.is_current
 LEFT JOIN public.zalo_users zu ON zu.id=c.zalo_user_id AND zu.account_id=c.account_id AND zu.staff_id=c.staff_id AND zu.organization_id=c.organization_id
 LEFT JOIN public.zalo_groups zg ON c.contact_type='group' AND c.extra_data->>'platform'='zalo' AND zg.account_id=c.account_id AND zg.staff_id=c.staff_id AND zg.organization_id=c.organization_id AND zg.zalo_group_id=c.uid
 LEFT JOIN public.zalo_group_members gm ON $4='group_members' AND gm.account_id=c.account_id AND gm.staff_id=c.staff_id AND gm.organization_id=c.organization_id AND gm.zalo_uid=c.uid AND gm.zalo_group_id=$3->>'zaloGroupId' AND gm.is_current
 LEFT JOIN public.zalo_groups mg ON mg.account_id=gm.account_id AND mg.staff_id=gm.staff_id AND mg.organization_id=gm.organization_id AND mg.zalo_group_id=gm.zalo_group_id
 WHERE c.staff_id=$1 AND c.organization_id=$2 AND c.account_id=($3->>'accountId')::bigint AND c.is_delete=false
 AND ($3->>'contactType' IS NULL OR c.contact_type=$3->>'contactType')
 AND (NOT ($3 ? 'datasetId') OR (dm.contact_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.auto_account_contacts_dataset d WHERE d.id=dm.dataset_id AND d.contact_type=c.contact_type)))
 AND (NOT ($3 ? 'contactGroupId') OR EXISTS(SELECT 1 FROM public.auto_account_contact_group_members g WHERE g.group_id=($3->>'contactGroupId')::bigint AND g.contact_id=c.id AND NOT g.is_delete))
 AND ($4<>'group_members' OR (gm.id IS NOT NULL AND c.contact_type='person'))
 AND (COALESCE($3->>'statusFilter','all')='all' OR c.contact_type NOT IN ('person','group') OR CASE WHEN $3->>'statusFilter'='active' THEN CASE c.contact_type WHEN 'person' THEN c.is_friend IS TRUE ELSE c.is_joined IS TRUE END ELSE CASE c.contact_type WHEN 'person' THEN c.is_friend IS NOT TRUE ELSE c.is_joined IS NOT TRUE END END)
 AND (NOT ($3 ? 'ids') OR c.id IN (SELECT jsonb_array_elements_text($3->'ids')::bigint))
 AND (NOT ($3 ? 'excludeIds') OR c.id NOT IN (SELECT jsonb_array_elements_text($3->'excludeIds')::bigint))
 AND (NULLIF(btrim($3->>'search'),'') IS NULL OR strpos(lower(normalize(concat_ws(' ',c.name,c.uid,c.extra_data->>'phone',c.extra_data->>'phoneNumber',c.extra_data->>'phone_number',c.extra_data->>'mobilePhone',c.extra_data->>'mobile_phone',c.extra_data#>>'{rawPayload,phone}',c.extra_data#>>'{rawPayload,phoneNumber}',c.extra_data#>>'{rawPayload,phone_number}',c.extra_data#>>'{rawPayload,mobilePhone}',c.extra_data#>>'{rawPayload,mobile_phone}'),NFC)),lower(normalize(btrim($3->>'search'),NFC)))>0)
 AND (NOT ($3 ?| ARRAY['source','sourcePostUrl','sourceProfileUrl','sourceGroupUrl']) OR private.column_filter_source_match_v1(c.extra_data,$3))
 AND ((COALESCE(jsonb_array_length($3->'zaloTagIds'),0)=0 AND NOT COALESCE(($3->>'zaloNoTag')::boolean,false)) OR private.column_filter_zalo_tags_v1(c.extra_data) && ARRAY(SELECT jsonb_array_elements_text($3->'zaloTagIds')) OR (COALESCE(($3->>'zaloNoTag')::boolean,false) AND cardinality(private.column_filter_zalo_tags_v1(c.extra_data))=0))
 AND ((COALESCE(jsonb_array_length($3->'akaBizTagIds'),0)=0 AND NOT COALESCE(($3->>'akaBizNoTag')::boolean,false)) OR COALESCE(c.akabiz_tag_ids,'{}'::bigint[]) && ARRAY(SELECT jsonb_array_elements_text($3->'akaBizTagIds')::bigint) OR (COALESCE(($3->>'akaBizNoTag')::boolean,false) AND COALESCE(cardinality(c.akabiz_tag_ids),0)=0))
), matched AS %4$s (SELECT id,sort_rank,sort_name,sort_time FROM candidate WHERE %1$s),
 page AS MATERIALIZED (SELECT * FROM matched WHERE %2$s ORDER BY sort_rank,sort_name,sort_time DESC,id OFFSET $5 LIMIT $6)
 SELECT jsonb_build_object('version',1,'total',%3$s,'rows',COALESCE((SELECT jsonb_agg(c.row_data ORDER BY p.sort_rank,p.sort_name,p.sort_time DESC,p.id) FROM page p JOIN candidate c ON c.id=p.id),'[]'::jsonb),
 'after',(SELECT jsonb_build_object('rank',sort_rank,'name',sort_name,'time',sort_time,'id',id::text) FROM page ORDER BY sort_rank DESC,sort_name DESC,sort_time,id DESC LIMIT 1),'hasMore',(SELECT count(*) FROM page)=$6)
 $query$;
 sql:=format(sql,predicate,cursor_clause,count_sql,CASE WHEN p_query->>'countMode'='none' THEN 'NOT MATERIALIZED' ELSE 'MATERIALIZED' END);
 EXECUTE sql INTO result USING p_staff_id,p_organization_id,p_query,p_source,page_offset,page_limit;
 RETURN result;
END $fn$;
REVOKE ALL ON FUNCTION public.aka_agent_read_filtered_contacts_v1(bigint,bigint,text,text,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aka_agent_read_filtered_contacts_v1(bigint,bigint,text,text,text,jsonb) TO anon,authenticated,service_role;

CREATE FUNCTION public.aka_agent_read_filtered_remarketing_v1(p_staff_id bigint,p_organization_id bigint,p_auth_username text,p_auth_password text,p_query jsonb)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET statement_timeout='60s' AS $fn$
DECLARE predicate text; sql text; result jsonb; page_limit integer; page_offset integer; key text; cursor_clause text:='true'; count_sql text; actions text[];
 allowed_actions constant text[]:=ARRAY['zalo_message_phone','zalo_message_friend','zalo_message_group_member','zalo_message_group_realtime','zalo_message_friend_recommendation'];
BEGIN
 PERFORM public.auto_assert_automation_identity(p_staff_id,p_organization_id,p_auth_username,p_auth_password);
 IF jsonb_typeof(p_query) IS DISTINCT FROM 'object' OR octet_length(p_query::text)>2097152 THEN RAISE EXCEPTION 'invalid_filter_query'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.org_staff s WHERE s.id=p_staff_id AND s.organization_id=p_organization_id AND s.is_active AND s.deleted_at IS NULL) OR NOT EXISTS(SELECT 1 FROM public.auto_accounts a WHERE a.id=(p_query->>'accountId')::bigint AND a.staff_id=p_staff_id AND a.organization_id=p_organization_id AND a.flatform_type='zalo' AND NOT a.is_delete) THEN RAISE EXCEPTION 'account_access_denied' USING ERRCODE='42501'; END IF;
 page_limit:=COALESCE((p_query->>'limit')::integer,100);page_offset:=COALESCE((p_query->>'offset')::integer,0);
 IF page_limit NOT BETWEEN 1 AND 500 OR page_offset NOT BETWEEN 0 AND 100000 THEN RAISE EXCEPTION 'invalid_filter_query'; END IF;
 FOREACH key IN ARRAY ARRAY['ids','excludeIds','zaloTagIds','akaBizTagIds','campaignActionIds'] LOOP
  IF p_query ? key AND (jsonb_typeof(p_query->key) IS DISTINCT FROM 'array' OR jsonb_array_length(p_query->key)>CASE WHEN key IN ('ids','excludeIds') THEN 100000 ELSE 1000 END) THEN RAISE EXCEPTION 'invalid_filter_query_array'; END IF;
  IF key<>'campaignActionIds' AND p_query->key='[]'::jsonb THEN p_query:=p_query-key; END IF;
 END LOOP;
 actions:=CASE WHEN p_query ? 'campaignActionIds' THEN ARRAY(SELECT jsonb_array_elements_text(p_query->'campaignActionIds')) WHEN nullif(p_query->>'campaignActionId','all') IS NOT NULL THEN ARRAY[p_query->>'campaignActionId'] ELSE allowed_actions END;
 actions:=ARRAY(SELECT v FROM unnest(actions) v WHERE v=ANY(allowed_actions));
 predicate:=private.column_filter_predicate_v1('remarketing',p_query->'columnFilters');
 IF p_query ? 'after' THEN
  IF page_offset<>0
   OR jsonb_typeof(p_query->'after') IS DISTINCT FROM 'object'
   OR jsonb_typeof(p_query#>'{after,id}') IS DISTINCT FROM 'string'
   OR (p_query#>>'{after,id}') !~ '^[1-9][0-9]{0,15}$'
   OR jsonb_typeof(p_query#>'{after,createdAt}') IS DISTINCT FROM 'string'
   OR (p_query#>>'{after,createdAt}') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$' THEN RAISE EXCEPTION 'invalid_filter_cursor' USING ERRCODE='22023'; END IF;
  BEGIN
   IF (p_query#>>'{after,id}')::bigint>9007199254740991 OR NOT isfinite((p_query#>>'{after,createdAt}')::timestamptz) THEN
    RAISE EXCEPTION 'invalid_filter_cursor' USING ERRCODE='22023';
   END IF;
   
  EXCEPTION WHEN data_exception THEN RAISE EXCEPTION 'invalid_filter_cursor' USING ERRCODE='22023'; END;
  cursor_clause:=$cursor$(created_at,id)<(($3#>>'{after,createdAt}')::timestamptz,($3#>>'{after,id}')::bigint)$cursor$;
 END IF;
 count_sql:=CASE WHEN p_query->>'countMode'='none' THEN 'NULL::bigint' ELSE '(SELECT count(*) FROM matched)' END;
 sql:=$query$
 WITH history AS MATERIALIZED (
 SELECT d.id,d.created_at,COALESCE(NULLIF(btrim(i.uid),''),NULLIF(btrim(d.data#>>'{target,uid}'),''),NULLIF(btrim(d.data#>>'{targetUid}'),''),NULLIF(btrim(d.data#>>'{uid}'),''),NULLIF(btrim(d.data#>>'{target,raw,inputData,uid}'),''),NULLIF(btrim(d.data#>>'{target,raw,profile,uid}'),'')) uid,COALESCE(NULLIF(btrim(i.name),''),NULLIF(btrim(d.data#>>'{target,displayName}'),''),NULLIF(btrim(d.data#>>'{target,originalName}'),''),NULLIF(btrim(d.data#>>'{target,raw,profile,displayName}'),''),NULLIF(btrim(d.data#>>'{target,raw,profile,zaloName}'),''),NULLIF(btrim(d.data#>>'{target,raw,profile,zalo_name}'),''),NULLIF(btrim(d.data#>>'{target,raw,inputData,name}'),'')) fallback_name,private.column_filter_phone_v1(i.phone) fallback_phone,COALESCE(NULLIF(btrim(d.data#>>'{target,originalName}'),''),NULLIF(btrim(d.data#>>'{target,raw,profile,zaloName}'),''),NULLIF(btrim(d.data#>>'{target,raw,profile,zalo_name}'),''),NULLIF(btrim(d.data#>>'{target,raw,inputData,originalName}'),'')) original_name
 FROM public.auto_campaign_details d JOIN public.auto_campaigns campaign ON campaign.id=d.campaign_id
 LEFT JOIN public.auto_campaign_input_data i ON i.id=d.input_data_id
 WHERE d.account_id=($3->>'accountId')::bigint AND NOT d.is_delete
 AND campaign.account_id=d.account_id AND campaign.staff_id=$1 AND campaign.organization_id=$2 AND NOT campaign.is_delete
 AND campaign.action_id=ANY($4) AND d.action_code IN ('zalo_message_stranger','zalo_message_friend')
 AND (nullif($3->>'dateFrom','') IS NULL OR d.created_at >= (nullif($3->>'dateFrom','')::date::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'))
 AND (nullif($3->>'dateTo','') IS NULL OR d.created_at < (((nullif($3->>'dateTo','')::date+1)::timestamp) AT TIME ZONE 'Asia/Ho_Chi_Minh'))
), rollup AS MATERIALIZED (
 SELECT lower(uid) uid_key,count(*) sent_count,(array_agg(id ORDER BY created_at DESC,id DESC))[1] latest_id,
 (array_agg(uid ORDER BY created_at DESC,id DESC))[1] uid,
 (array_agg(fallback_name ORDER BY created_at DESC,id DESC) FILTER (WHERE fallback_name IS NOT NULL AND fallback_name<>uid))[1] fallback_name,
 (array_agg(fallback_phone ORDER BY created_at DESC,id DESC) FILTER (WHERE fallback_phone IS NOT NULL))[1] fallback_phone,
 (array_agg(original_name ORDER BY created_at DESC,id DESC) FILTER (WHERE original_name IS NOT NULL))[1] original_name
 FROM history WHERE uid IS NOT NULL GROUP BY lower(uid)
), candidate AS NOT MATERIALIZED (
 SELECT d.id,d.created_at,($3->>'accountId')::bigint account_id,CASE WHEN u.is_fr=1 OR c.is_friend IS TRUE THEN true WHEN (u.zalo_uid IS NOT NULL AND COALESCE(u.is_fr,0)=0) OR c.is_friend IS FALSE THEN false END is_friend,c.akabiz_tag_ids,
 COALESCE(c.extra_data,'{}'::jsonb)||jsonb_build_object('source','zalo_remarketing_customers','latestCampaignId',campaign.id,'latestCampaignName',campaign.name,'latestCampaignActionId',campaign.action_id,'latestCampaignActionName',COALESCE(NULLIF(action.name,''),campaign.action_id),'latestErrorCode',d.error_code,'originalName',COALESCE(NULLIF(btrim(u.zalo_name),''),NULLIF(btrim(u.display_name),''),NULLIF(btrim(r.original_name),'')),'gender',u.gender) extra_data,
 COALESCE(NULLIF(btrim(c.name),''),NULLIF(btrim(u.display_name),''),NULLIF(btrim(u.zalo_name),''),NULLIF(btrim(r.fallback_name),''),NULLIF(btrim(r.uid),'')) AS "f_name",
r.uid AS "f_uid",
COALESCE(private.column_filter_phone_v1(COALESCE(NULLIF(btrim(u.phone_number),''),NULLIF(btrim(u.raw_payload->>'phoneNumber'),''),NULLIF(btrim(u.raw_payload->>'phone_number'),''),NULLIF(btrim(u.raw_payload->>'phone'),''))),private.column_filter_phone_v1(COALESCE(NULLIF(btrim(c.extra_data->>'phone'),''),NULLIF(btrim(c.extra_data->>'phoneNumber'),''),NULLIF(btrim(c.extra_data->>'phone_number'),''),NULLIF(btrim(c.extra_data->>'mobilePhone'),''),NULLIF(btrim(c.extra_data->>'mobile_phone'),''))),r.fallback_phone) AS "f_phone",
g.name AS "f_groupName",
campaign.action_id AS "f_latestAction",
r.sent_count AS "f_sentCount",
d.created_at AS "f_latestSentAt",
(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date-(d.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date AS "f_daysSinceLatest",
d.status AS "f_latestStatus",
d.log AS "f_latestLog",
CASE WHEN (CASE WHEN u.is_fr=1 OR c.is_friend IS TRUE THEN true WHEN (u.zalo_uid IS NOT NULL AND COALESCE(u.is_fr,0)=0) OR c.is_friend IS FALSE THEN false END) THEN 'Bạn bè' WHEN NOT (CASE WHEN u.is_fr=1 OR c.is_friend IS TRUE THEN true WHEN (u.zalo_uid IS NOT NULL AND COALESCE(u.is_fr,0)=0) OR c.is_friend IS FALSE THEN false END) THEN 'Chưa kết bạn' END AS "f_recipientStatus",
private.column_filter_zalo_tags_v1(c.extra_data) AS "f_zaloTags",
c.akabiz_tag_ids::text[] AS "f_akaBizTags"
 FROM rollup r JOIN public.auto_campaign_details d ON d.id=r.latest_id JOIN public.auto_campaigns campaign ON campaign.id=d.campaign_id
 LEFT JOIN public.auto_campaign_actions action ON action.id=campaign.action_id
 LEFT JOIN public.auto_account_contacts c ON c.account_id=campaign.account_id AND c.staff_id=$1 AND c.organization_id=$2 AND c.uid=r.uid AND c.contact_type='person' AND NOT c.is_delete
 LEFT JOIN public.zalo_users u ON u.account_id=campaign.account_id AND u.staff_id=$1 AND u.organization_id=$2 AND u.zalo_uid=r.uid
 LEFT JOIN LATERAL (SELECT m.zalo_group_id FROM public.zalo_group_members m WHERE m.account_id=campaign.account_id AND m.staff_id=$1 AND m.organization_id=$2 AND m.zalo_uid=r.uid ORDER BY m.is_current DESC,m.last_seen_at DESC,m.updated_at DESC,m.id DESC LIMIT 1) member ON nullif(btrim(COALESCE(c.extra_data->>'zaloGroupId',c.extra_data->>'zalo_group_id')),'') IS NULL
 LEFT JOIN public.zalo_groups g ON g.account_id=campaign.account_id AND g.staff_id=$1 AND g.organization_id=$2 AND g.zalo_group_id=COALESCE(NULLIF(btrim(c.extra_data->>'zaloGroupId'),''),NULLIF(btrim(c.extra_data->>'zalo_group_id'),''),NULLIF(btrim(member.zalo_group_id),''))
), filtered AS NOT MATERIALIZED (SELECT * FROM candidate WHERE %1$s
 AND (NOT ($3 ? 'ids') OR id IN (SELECT jsonb_array_elements_text($3->'ids')::bigint))
 AND (NOT ($3 ? 'excludeIds') OR id NOT IN (SELECT jsonb_array_elements_text($3->'excludeIds')::bigint))
 AND (NULLIF(btrim($3->>'search'),'') IS NULL OR strpos(lower(normalize(concat_ws(' ',f_name,f_uid,f_phone,extra_data->>'phoneNumber',extra_data->>'phone_number',extra_data->>'mobilePhone',extra_data->>'mobile_phone'),NFC)),lower(normalize(btrim($3->>'search'),NFC)))>0)
 AND ((COALESCE(jsonb_array_length($3->'zaloTagIds'),0)=0 AND NOT COALESCE(($3->>'zaloNoTag')::boolean,false)) OR "f_zaloTags" && ARRAY(SELECT jsonb_array_elements_text($3->'zaloTagIds')) OR (COALESCE(($3->>'zaloNoTag')::boolean,false) AND cardinality("f_zaloTags")=0))
 AND ((COALESCE(jsonb_array_length($3->'akaBizTagIds'),0)=0 AND NOT COALESCE(($3->>'akaBizNoTag')::boolean,false)) OR COALESCE(akabiz_tag_ids,'{}'::bigint[]) && ARRAY(SELECT jsonb_array_elements_text($3->'akaBizTagIds')::bigint) OR (COALESCE(($3->>'akaBizNoTag')::boolean,false) AND COALESCE(cardinality(akabiz_tag_ids),0)=0))
 ), matched AS %4$s (SELECT id,created_at FROM filtered),
 page AS MATERIALIZED (SELECT * FROM matched WHERE %2$s ORDER BY created_at DESC,id DESC OFFSET $5 LIMIT $6)
 SELECT jsonb_build_object('version',1,'total',%3$s,'rows',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',c.id,'account_id',c.account_id,'contact_type','person','name',c.f_name,'uid',c.f_uid,'url','','is_delete',false,'is_friend',c.is_friend,'akabiz_tag_ids',c.akabiz_tag_ids,
 'extra_data',c.extra_data||jsonb_build_object('phone',c.f_phone,'groupName',c."f_groupName",'sentCount',c."f_sentCount",'latestSentAt',c."f_latestSentAt",'latestSentDate',to_char(c."f_latestSentAt" AT TIME ZONE 'Asia/Ho_Chi_Minh','DD/MM/YYYY'),'daysSinceLatest',c."f_daysSinceLatest",'latestStatus',c."f_latestStatus",'latestLog',c."f_latestLog",'recipientStatus',c."f_recipientStatus")) ORDER BY p.created_at DESC,p.id DESC) FROM page p JOIN filtered c ON c.id=p.id),'[]'::jsonb),
 'after',(SELECT jsonb_build_object('createdAt',created_at,'id',id::text) FROM page ORDER BY created_at,id LIMIT 1),'hasMore',(SELECT count(*) FROM page)=$6)
 $query$;
 sql:=format(sql,predicate,cursor_clause,count_sql,CASE WHEN p_query->>'countMode'='none' THEN 'NOT MATERIALIZED' ELSE 'MATERIALIZED' END);
 EXECUTE sql INTO result USING p_staff_id,p_organization_id,p_query,actions,page_offset,page_limit;
 RETURN result;
END $fn$;
REVOKE ALL ON FUNCTION public.aka_agent_read_filtered_remarketing_v1(bigint,bigint,text,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aka_agent_read_filtered_remarketing_v1(bigint,bigint,text,text,jsonb) TO anon,authenticated,service_role;

COMMIT;
